-- GENERATED by `wfj generate` from data/book/. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("book", {
  ["c70ac10395b8b08e"] = { "I druidi elfi della notte, compreso Malfurion stesso, furono legati al Sogno attraverso l'Albero del Mondo. Come parte del patto mistico, i druidi accettarono di dormire per secoli interi, così che i loro spiriti potessero vagare per gli infiniti Sentieri del Sogno di Ysera. Benché i druidi fossero addolorati all'idea di perdere tanti anni della loro vita nel letargo, accettarono altruisticamente di rispettare il patto con Ysera.", "." },
  ["c72fea4210d135ac"] = { "Salve, {name}. A quanto pare, da quel biglietto è venuta fuori qualche informazione.\n\nSu James, temo, ho trovato ben poco. Ho però scoperto qualcosa sulla famiglia di Amelia.\n\nAnche se né lei né i suoi figli sono sopravvissuti alla guerra, suo fratello sì: un uomo di nome Alexander Calder. Lo trovi nella Forlorn Cavern di ⟦Ironforge=Forgiardente⟧, dove studia la pericolosa magia della Legione Infuocata.\n\nAveva anche una cugina a cui era molto legata, una donna oggi nota come Deze Snowbane, che a Orgrimmar promuove la battaglia per il ⟦Arathi Basin=Bacino d'Arathi⟧.\n\nDovresti far visita a uno dei due la prossima volta che passi da quelle parti. Di certo vorranno sapere della loro Amelia perduta, se non altro.", "." },
  ["c7466ecb8e38ae6e"] = { "Anche il possente Archimonde diede potere a dei propri agenti. Chiamando a sé i malefici signori degli abissi e il loro barbaro capo, Mannoroth il Distruttore, Archimonde sperava di formare un'élite combattente che spazzasse via ogni forma di vita dal creato.", "." },
  ["c75a1dc10926452a"] = { "ha avuto la meglio su quel bruto ripugnante, ma ora si sta curando un brutto taglio al braccio. Pare che per un po' le faccende toccheranno a me.\n\nTERZO GIORNO\n\nFreddo. Ha nevicato un po' verso mezzogiorno.\n\nQUARTO GIORNO\n\nOggi il ragazzo era di nuovo in piedi e di buon umore, così abbiamo dato una prima occhiata ai troll. ⟦Frostmane=Mantogelido⟧, direi, a giudicare dai segni sulla pelle e dai vari ninnoli che portavano addosso.", "." },
  ["c79edb0b6c529005"] = { "Quando si risvegliò dal coma, scoprì di essere diventato adulto e che i suoi amici Llane e Anduin erano diventati i reggenti di Azeroth. Benché desiderasse usare gli incredibili poteri appena scoperti per proteggere la terra che chiamava casa, lo spirito oscuro di Sargeras piegava i suoi pensieri e le sue emozioni verso un fine insidioso.", "." },
  ["c7bf41a4cecd7cae"] = { "Devlin si è lasciato vincere dalla disperazione e ha cercato una via di fuga dalla nostra cattiva sorte, e così ha stretto un patto con il Flagello. Non so quale prezzo gli sia stato promesso per il suo tradimento, ma sono certo che fosse intriso di menzogne.\n\nSe vedi mio fratello, fuggi da lui. È un demonio. Qualche notte fa ha ucciso due delle nostre sentinelle e ha fatto passare un piccolo gruppo del Flagello attraverso la breccia, guidandolo fin dove molti di noi dormivano.", "." },
  ["c7d9118ed5d163b9"] = { "Con quanta gioia laverei con le mie lacrime ogni piccola macchia sulla tua felicità, e lotterei con tutte le sventure di questo mondo per proteggere te e i miei cari figli da ogni male.\n\nMa non posso.\n\nDovrò vegliare su di te dalla Distorsione Fatua e aleggiarti accanto mentre affronti le tempeste con il tuo piccolo, prezioso carico, e attendere con triste pazienza il giorno in cui ci ritroveremo per non separarci mai più.", "." },
})
